def extra_pages(lang):
    def entry(slug, title, intro, sections):
        return dict(slug=slug, title=title, group='About Miblo' if lang=='en' else 'À propos de Miblo', intro=intro,
                    sections=[dict(id=i,title=t,body=b) for i,t,b in sections])
    return [
        entry('questions', 'Miblo CLI: questions and answers' if lang=='en' else 'Miblo CLI : questions fréquentes',
              'What Miblo generates, which databases it supports and how to use the resulting Rust API.' if lang=='en' else 'Ce que Miblo génère, les bases prises en charge et comment utiliser l’API Rust obtenue.', FAQ[lang]),
        entry('confidentialite', 'Privacy and cookies' if lang=='en' else 'Confidentialité et cookies',
              'Choose whether this website uses Google Analytics, and understand what it measures.' if lang=='en' else 'Choisir la mesure d’audience de ce site avec Google Analytics et comprendre les données mesurées.', PRIVACY[lang]),
    ]
